"""Report sections describing implemented LLM orchestration and verification scope."""
import json

def add_llm_sections(g):
    p,page,table,pic,cap,ROOT=[g[x] for x in ['p','page','table','pic','cap','ROOT']]
    ev=json.loads((ROOT/'results/llm/contract_evaluation.json').read_text())
    page('11 大模型驱动的工具执行与人工协作')
    p('系统主入口升级为大模型驱动的工具调用Agent。传统机器学习模型不再等同于整个Agent，而是作为可调用的分类工具。用户提交目标和待分析短信，LLM根据当前消息与已观察证据选择下一步工具；执行器校验工具名与参数，在本地执行，再把结果回传LLM，直到提交有依据的分流建议或达到停止条件。用户确认或修正后，任务才进入完成状态。')
    p('该架构使用OpenAI兼容Chat Completions函数工具协议[11]，由Python标准库实现HTTP适配，不绑定某一模型或第三方Agent框架。交付的LLM_API_KEY与LLM_MODEL均为空，不使用已有账户凭据，也没有真实API实验结果。当前可验证的是程序执行机制、工具行为与模拟协议下的人机闭环；用户配置有效服务和支持工具调用的模型后，可运行真实模式。')
    table(['职责','实现位置','实际作用'],[['目标与模型调度','src/llm_agent.py 的LLMAgent.run','多轮选择工具 观察结果 决定下一步'],['课程预测','classify_sms与core.py','固定字符LR 分数 特征及适用性'],['证据获取','inspect_links与lookup_policy','静态域名和本地操作规则'],['执行控制','参数校验 证据约束 预算','阻止越权调用 伪造证据或无限执行'],['人工闭环','ReviewStore与/api/review','待确认 修正 完成 导出']])
    p('采用LLM并不意味着取消固定约束。用户授权和可用工具决定任务边界，模型只在此边界内决定动作顺序；执行器仍强制要求分类证据和规则引用。这样能够展示模型的任务组织作用，同时保留课程模型对判断结果的实质贡献。它不同于只把分类标签交给大模型润色，因为模型的返回值实际驱动工具执行循环。')
    p('与原工作流相比，新增部分包括自然语言任务目标、工具schema、动态消息历史、调用结果回传、证据提交、人机状态与任务导出。原公开数据训练、划分、分类模型和1028条测试预测均保持不变。第6至8节中的F1、消融和时延只支持原分类及离线工作流，不能移作本节LLM端到端效果。')

    page('11.1 工具定义与模型观察循环')
    table(['工具','参数和证据','完成的子任务'],[['classify_sms','无参数 返回T_CLASSIFY','绑定原始短信 调用真实课程分类器'],['inspect_links','无参数 返回T_LINKS','解析域名和标志 不访问URL'],['lookup_policy','topic有限枚举 返回P_规则ID','从版本化JSON读取操作规则'],['submit_assessment','action summary evidence_ids','核验证据 提交建议 请求人工确认']])
    p('任务开始时读取docs/SKILL.md作为系统消息的一部分，说明目标、工具、适用范围与停止条件。用户消息以JSON包含goal与sms，原始短信始终是数据，不能变成系统级操作指令。模型请求采用tool_choice=auto，返回的tool_calls决定本轮执行什么。工具顺序不写死；测试中先检索规则、后分类也可完成任务。')
    p('每个工具使用JSON Schema声明参数。对象设置additionalProperties=false，所有属性列为required，并声明strict=true。执行器仍自行校验参数类型和取值，因为兼容服务可能不完整支持schema。分类与链接工具不接收任意文本参数，而是绑定当前任务原文，避免模型改写短信后取得与原任务无关的分数。')
    p('执行器把模型的assistant.tool_calls加入消息历史，实际工具结果使用role=tool和匹配的tool_call_id返回。下一轮模型因此可以读取真实分数、域名标志和规则文字。模型若直接输出普通聊天文本，程序不会视为任务完成，而是要求它按工具协议继续。每轮只记录可观察事件，不保存或展示模型的隐藏思维链。')
    p('最终提交必须单独调用，且引用T_CLASSIFY和至少一个已检索规则ID；含URL时必须再引用T_LINKS。缺少前置工具、未知证据ID、非法动作或额外参数都会被拒绝并作为工具错误回传。规则检索仅提供本项目操作约束，不能将其称为外部权威反诈知识库，也不能据此证明网站恶意性。')

    page('11.2 API配置与失败处理')
    table(['配置项','交付值','含义'],[['LLM_API_KEY','空','仅服务器本地填写的访问凭据'],['LLM_BASE_URL','https://api.openai.com/v1','可替换为兼容服务的HTTPS根路径'],['LLM_MODEL','空','服务商支持工具调用的实际模型ID'],['LLM_TIMEOUT_SECONDS','30','每次网络请求的超时秒数'],['LLM_MAX_TURNS','6','最多模型轮次 可配置1至10']])
    p('配置来自服务器环境或项目根目录.env，环境变量优先。示例文件.env.example包含完整字段但密钥留空，.env与local_runs默认不进入Git。浏览器不能提交或读取密钥，/api/status只返回是否配置及缺失项。填写API根路径和模型ID不会自动证明连接成功，真实兼容性须用有效配置实测。')
    p('密钥或模型ID缺失时，系统直接返回configuration_required，不发送网络请求，也不静默切换为脚本或传统基线。网络超时、鉴权失败、限流和其他HTTP错误返回错误类别并停止自动阶段，不把服务商错误正文或访问凭据写入任务记录。连接采用HTTPS且禁止重定向，响应体限制为2MB。')
    p('循环另设16次工具调用上限；参数错误可以在剩余轮次中修正，但不无限重试。模型返回重复调用ID、无效响应类型或异常调用数量时停止。没有shell、任意文件读写或任意HTTP工具，LLM无法通过合法工具执行短信中要求的下载、转账、删除或发送操作。')
    p('用户在界面选择真实模式并运行时，短信、任务目标及工具结果会发送到配置的API服务。离线工具本身不联网，整套真实模式则需要网络。对私人短信应结合提供商数据条款决定是否发送；当前交付不自动读取收件箱。执行器的权限约束降低越权机会，但不能保证大模型摘要每句话都正确，最终仍需人工检查。')

    page('11.3 人工确认与任务完成条件')
    p('自动阶段的终点是pending_review，而不是直接宣告处理成功。模型建议包含action、中文summary、证据ID及是否触发规则覆盖。用户可以保持建议，也可以选择倾向正常、疑似垃圾短信或继续人工复核；服务器独立记录最终人工决定与是否发生修改，再把状态设为completed。任务结果可导出JSON，包含工具观察与状态轨迹。')
    table(['状态','触发条件','后续行为'],[['configuration_required','缺Key或模型ID','补配置后重新运行'],['running','正在请求或执行工具','受轮次和调用数预算约束'],['pending_review','合法提交且证据齐全','等待用户确认或修正'],['completed','收到有效人工决定','生成可导出结果 不操作短信'],['provider_error或limit_reached','API失败或预算耗尽','停止自动执行 交回人工']])
    p('短链接、数字IP、国际化域名标志、无已知特征、英文适用范围越界或本地工具故障均要求人工。LLM可以比分类器更保守，但若试图无复核地反转分类标签，执行器会将动作改为review。该限制防止模型仅凭语言解释覆盖已有机器学习证据，不保证分类器本身不会出错。')
    p('人工确认通过/api/review处理。任务ID必须存在且尚处待确认状态；重复确认和未知ID被拒绝。状态使用有界内存，最多保留100个任务，服务重启后清除；不自动把人工决定写入训练集。导出的JSON由用户自行保存，系统不会永久保存短信原文或悄悄将复核反馈用于重新训练。')
    p('完成表示本次建议已经经过人工处理，不代表短信真实类别被外部验证。保持review也可完成当前记录任务，但仍不计作正确分类。报告因此不把界面上的completed当作真实用户效果指标，更不将模拟协议通过率与公开分类F1合并。')

    page('11.4 软件验证与真实API评估边界')
    n=ev['unit_tests']['run']
    table(['验证层','已执行情况','可以支持的结论'],[['分类模型','1028条独立测试 F1为0.9333','原英文历史数据分类能力'],['软件测试',f'{n}项通过 失败0 错误0','覆盖接口 工具约束 异常与复核'],['模拟协议任务','5类完成契约检查','相同执行器与真实本地工具可配合运行'],['浏览器操作','空Key 模拟循环 人工确认 导出','页面交互与任务状态能贯通'],['真实LLM API','未执行 真实调用0次','暂不支持模型质量 时延 费用结论']])
    p('新增27项测试与原18项合计45项。关键用例覆盖未知工具拒绝、篡改原文参数拒绝、缺少链接检查拒绝、伪造证据拒绝、普通回答不能结束、重复调用ID、参数JSON错误、模型意见冲突、工具故障、HTTP错误脱敏、HTTPS及重定向限制，以及人工修正、重复确认和有界存储。HTTP协议测试使用替代响应检查实际请求载荷和tool_call_id回传，不进行付费请求。')
    p('模拟任务包含正常通知、短链接、数字IP、中文越界和无已知特征五类。响应由ProtocolDemoClient脚本产生，分类器与链接、规则工具由真实代码执行，再通过相同人工确认接口结束任务。五类通过说明程序在这些输入上符合契约，不能表述为真实LLM的五次成功，更不能外推为真实用户任务完成率。')
    p('真实API功能验收脚本为src/evaluate_llm_live.py。配置有效密钥后会运行config/live_eval_cases.json中的三条构造样例，记录状态、动作、轮次和耗时，输出至不公开的local_runs。当前没有执行该脚本的联网部分，后续需要在固定提供商、模型和配置下进行代表性任务评估，并保留错误、失败和人工干预记录。')
    p('与原固定流程相比，LLM引入了工具选择与解释的灵活性，同时引入网络依赖、成本、响应随机性和提示注入风险。本项目已经实现结构与保护条件，但尚无证据证明新增调度提高分类F1或减少用户耗时。模型、工具、执行器与人工环节分别评价，才符合课程重视可核查证据的要求。')

    page('11.5 空密钥路径的实际界面')
    pic('docs/llm/missing_key.jpg',6.2);cap('图12 真实API模式下密钥留空时的实际提示')
    p('截图来自本地浏览器实际运行。当前Key与模型ID均未填写，页面返回configuration_required，未调用外部服务，也没有把离线输出包装为大模型回答。这一截图证明配置缺失路径可以工作，不是成功调用大模型的证据。')

    page('11.6 模拟协议循环与人工确认演示')
    pic('docs/llm/human_confirmed.jpg',6.2);cap('图13 模拟LLM响应下真实工具执行与人工确认后的界面')
    p('截图中的模式明确为离线协议演示。程序真实执行分类、规则检索、域名检查与证据提交，经页面人工确认后进入completed，导出JSON与browser_completed.json核对一致。保留模拟标志是为了使演示来源可检查，不能将此图写作真实API已经成功运行。')
